import { HttpClient } from '@angular/common/http';
import { Component } from '@angular/core';
import { Chart } from 'chart.js';
import { NarudzbineService } from '../narudzbine.service';

@Component({
  selector: 'app-statistika',
  templateUrl: './statistika.component.html',
  styleUrls: ['./statistika.component.css']
})
export class StatistikaComponent {
  salesChart: Chart | undefined;

  constructor(private http: HttpClient, private ordersService: NarudzbineService) {}

  ngOnInit(): void {
    this.fetchSalesData();
  }

  fetchSalesData() {
    document.getElementById('loading')!.style.display = 'block'; // Prikazuje loading poruku
    this.ordersService.getStatistika() // Poziva servis za preuzimanje podataka
        .subscribe(data => {
            document.getElementById('loading')!.style.display = 'none'; // Sakriva loading poruku
            if (data.length > 0) {
                this.createChart(data); // Kreira grafikon sa dobijenim podacima
            } else {
                document.getElementById('no-data')!.style.display = 'block'; // Prikazuje poruku kada nema podataka
            }
        }, error => {
            document.getElementById('loading')!.style.display = 'none'; // Sakriva loading poruku u slučaju greške
            console.error('Greška prilikom dohvatanja podataka:', error);
        });
  }

  createChart(data: number[]) {
    const ctx = document.getElementById('salesChart') as HTMLCanvasElement;

    this.salesChart = new Chart(ctx, {
      type: 'bar',
      data: {
        labels: ['Januar', 'Februar', 'Mart', 'April', 'Maj', 'Jun', 'Jul', 'Avgust', 'Septembar', 'Oktobar', 'Novembar', 'Decembar'],
        datasets: [{
          label: 'Broj narudžbina',
          data: data,
          backgroundColor: 'rgba(75, 192, 192, 0.2)',
          borderColor: 'rgba(75, 192, 192, 1)',
          borderWidth: 1
        }]
      },
      options: {
        scales: {
          y: {
            beginAtZero: true
          }
        }
      }
    });
  }
}
<div class="statistika-container">
    <h1>Statistika Narudžbina</h1>

    <div class="chart-container">
        <canvas id="salesChart"></canvas>
    </div>

    <div id="loading" class="loading">Učitavanje podataka...</div>
    <div id="no-data" class="no-data" style="display: none;">Nema podataka za prikaz.</div>
</div>
